<?php
namespace qqworld_collector\module\collect_item; use qqworld_collector\lib; class featured_image extends lib { var $guid; public function init() { add_filter( 'qqworld-collector-collecting-engine-collect-item-' . $this->guid, array($this, 'filter'), 10, 7 ); add_filter( 'qqworld-collector-collecting-engine-collect-item-after-filter-' . $this->guid, array($this, 'after_filter'), 10, 6 ); } public function filter($items, $args, $source_link, $html, $download_args, $settings, $mode) { if (!empty($items)) foreach ($items as &$item) { $item = stripslashes($item); } return $items; } public function after_filter($items, $args, $source_link, $html, $settings, $mode) { $items = apply_filters( 'qqworld-collector-convert-relative-url-to-absolute-url', $items, $source_link ); return $items; } } ?>